import icontract


def is_lower_case(c: str) -> bool:
    return 'a' <= c <= 'z'


def shift_minus32(c: str) -> str:
    return chr((ord(c) - 32) % 128)


@icontract.ensure(lambda s, result: len(result) == len(s))
@icontract.ensure(lambda s, result: len(result) == len(s) and all(
    (result[i] == shift_minus32(s[i])) if is_lower_case(s[i]) else (result[i] == s[i]) for i in range(len(s))))
def toUppercase(s: str) -> str:
    chars = []
    for c in s:
        if 'a' <= c <= 'z':
            chars.append(chr(ord(c) - 32))
        else:
            chars.append(c)
    return ''.join(chars)
